  public static void Upgrade(){EditorSceneManager.OpenScene(WifeAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<WifeMatch>();Install(m);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();}
  public static void Install(WifeMatch m){GroundRocks(m);GroundTextures(m);Finish(m);Weather(m);EditorUtility.SetDirty(m);}
  static void GroundRocks(WifeMatch m){var report=new StringBuilder();int corrected=0,colliders=0;foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>()){if(t.name!="Installed Toon Gas Station rock")continue;float gap=SupportGap(t,m.course);report.AppendLine("BEFORE p="+t.position+" lowestActualVertexGap="+gap);if(gap>.08f||gap<-.65f){var terrain=m.course.terrain;var normalized=t.position-terrain.transform.position;var normal=terrain.terrainData.GetInterpolatedNormal(Mathf.Clamp01(normalized.x/terrain.terrainData.size.x),Mathf.Clamp01(normalized.z/terrain.terrainData.size.z));t.rotation=Quaternion.FromToRotation(t.up,normal)*t.rotation;float actual=SupportGap(t,m.course);t.position+=Vector3.up*(-.06f-actual);corrected++;EditorUtility.SetDirty(t);}foreach(var filter in t.GetComponentsInChildren<MeshFilter>(true)){if(filter.sharedMesh==null||filter.GetComponent<Collider>()!=null)continue;var shape=filter.gameObject.AddComponent<MeshCollider>();shape.sharedMesh=filter.sharedMesh;filter.gameObject.isStatic=true;colliders++;}report.AppendLine("AFTER p="+t.position+" lowestActualVertexGap="+SupportGap(t,m.course));}report.AppendLine("corrected="+corrected+" newStaticMeshColliders="+colliders+"; actual imported mesh vertices read through public Editor MeshUtility, no importer or vendor source changes.");System.IO.Directory.CreateDirectory("Logs/TruckSports/EssentialRelease/Wife");System.IO.File.WriteAllText("Logs/TruckSports/EssentialRelease/Wife/rock-support-audit.txt",report.ToString());}
  static void GroundTextures(WifeMatch m){var data=m.course.terrain.terrainData;var layers=data.terrainLayers;if(layers.Length==0||AssetDatabase.GetAssetPath(layers[0])!="Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer")return;const string path="Assets/TruckWifeCarrying/Materials/Country meadow grass.terrainlayer";var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>(path);if(layer==null){layer=UnityEngine.Object.Instantiate(layers[0]);layer.name="Country meadow grass";layer.tileSize=Vector2.one*16;layer.normalScale=.65f;AssetDatabase.CreateAsset(layer,path);}layers[0]=layer;data.terrainLayers=layers;EditorUtility.SetDirty(data);}
  static float SupportGap(Transform root,WifeCourse course){float min=float.PositiveInfinity;foreach(var filter in root.GetComponentsInChildren<MeshFilter>(true)){if(filter.sharedMesh==null)continue;using(var data=MeshUtility.AcquireReadOnlyMeshData(filter.sharedMesh))using(var vertices=new NativeArray<Vector3>(data[0].vertexCount,Allocator.Temp)){data[0].GetVertices(vertices);for(int i=0;i<vertices.Length;i++){var p=filter.transform.TransformPoint(vertices[i]);min=Mathf.Min(min,p.y-course.Height(p));}}}if(float.IsPositiveInfinity(min))throw new Exception("Authored country rock has no readable native mesh geometry");return min;}
  static void Finish(WifeMatch m){if(GameObject.Find("Terrain-fitted checkered country finish")!=null)return;var root=new GameObject("Terrain-fitted checkered country finish").transform;var black=SportsEventAuthoring.Mat(Folder,"Finish charcoal",new Color(.018f,.022f,.028f));var white=SportsEventAuthoring.Mat(Folder,"Finish warm ivory",new Color(.94f,.92f,.82f));black.shader=white.shader=Shader.Find("Universal Render Pipeline/Unlit");var vertices=new List<Vector3>();var triangles=new[]{new List<int>(),new List<int>()};Vector3 center=m.course.Point(WifeCourse.Finish),forward=Vector3.ProjectOnPlane(m.course.Point(WifeCourse.Finish+.5f)-m.course.Point(WifeCourse.Finish-.5f),Vector3.up).normalized,right=Vector3.Cross(Vector3.up,forward);const int columns=32,rows=3;for(int row=0;row<rows;row++)for(int col=0;col<columns;col++){float x0=-23+col*46f/columns,x1=x0+46f/columns,z0=-1.5f+row,z1=z0+1;int start=vertices.Count;foreach(var p in new[]{center+right*x0+forward*z0,center+right*x1+forward*z0,center+right*x1+forward*z1,center+right*x0+forward*z1}){var q=p;q.y=m.course.Height(q)+.045f;vertices.Add(q);}triangles[(row+col)%2].AddRange(new[]{start,start+2,start+1,start,start+3,start+2});}var mesh=new Mesh{name="Terrain-fitted official country finish checker mesh"};mesh.SetVertices(vertices);mesh.subMeshCount=2;for(int i=0;i<2;i++)mesh.SetTriangles(triangles[i],i);mesh.RecalculateNormals();mesh.RecalculateBounds();const string path="Assets/TruckWifeCarrying/Models/Official country finish checkers.asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved==null){AssetDatabase.CreateAsset(mesh,path);saved=mesh;}else{EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);}root.gameObject.AddComponent<MeshFilter>().sharedMesh=saved;root.gameObject.AddComponent<MeshRenderer>().sharedMaterials=new[]{black,white};
   var arch=new GameObject("Country finish banner and flags").transform;arch.SetParent(root,false);arch.SetPositionAndRotation(center,Quaternion.LookRotation(forward));for(int side=-1;side<=1;side+=2){var post=new GameObject("Actual timber finish post").transform;post.SetParent(arch,false);post.localPosition=new Vector3(side*24,0,0);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(post,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Planks01 Variant.prefab",new Vector3(.5f,6.8f,.5f),0,true,Folder);}var flagVertices=new List<Vector3>();var flagTris=new[]{new List<int>(),new List<int>()};for(int row=0;row<2;row++)for(int col=0;col<32;col++){int start=flagVertices.Count;float x=-24+col*1.5f,y=5.8f+row*.6f;flagVertices.AddRange(new[]{new Vector3(x,y,0),new Vector3(x+1.5f,y,0),new Vector3(x+1.5f,y+.6f,0),new Vector3(x,y+.6f,0)});flagTris[(row+col)%2].AddRange(new[]{start,start+1,start+2,start,start+2,start+3,start,start+2,start+1,start,start+3,start+2});}var flags=new Mesh{name="Original country checkered finish banner"};flags.SetVertices(flagVertices);flags.subMeshCount=2;for(int i=0;i<2;i++)flags.SetTriangles(flagTris[i],i);flags.RecalculateNormals();flags.RecalculateBounds();const string flagPath="Assets/TruckWifeCarrying/Models/Country checkered finish banner.asset";var asset=AssetDatabase.LoadAssetAtPath<Mesh>(flagPath);if(asset==null){AssetDatabase.CreateAsset(flags,flagPath);asset=flags;}else UnityEngine.Object.DestroyImmediate(flags);arch.gameObject.AddComponent<MeshFilter>().sharedMesh=asset;arch.gameObject.AddComponent<MeshRenderer>().sharedMaterials=new[]{black,white};var lettering=new GameObject("Depth-tested finish lettering").AddComponent<TMPro.TextMeshPro>();lettering.transform.SetParent(arch,false);lettering.transform.localPosition=new Vector3(0,7.8f,-.06f);lettering.font=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme").headingFont;lettering.text="FINISH";lettering.fontSize=18;lettering.enableAutoSizing=false;lettering.alignment=TMPro.TextAlignmentOptions.Center;lettering.color=SportsBroadcastCanvas.Cream;lettering.isOverlay=false;lettering.rectTransform.sizeDelta=new Vector2(30,4);}
  static void Weather(WifeMatch m){var cameras=m.views.views.Select(view=>view.view).Concat(new[]{m.views.broadcast.view}).ToArray();var catalog=SportsWeatherPresetsAuthoring.EnsureCatalog();m.course.weather.presets=catalog;SportsWeatherRenderingAuthoring.Install(m.gameObject,cameras,Folder);SportsScenicGradeAuthoring.Install(m.gameObject,cameras,Folder,-.35f);SportsWeatherPickerAuthoring.Install(m,catalog,new Vector2(0,336));m.menus.pages[0].transform.Find("Title").GetComponent<RectTransform>().anchoredPosition=new Vector2(0,430);foreach(var text in m.menus.pages[0].GetComponentsInChildren<TMPro.TMP_Text>(true))if(text.name=="Weather selection explanation")text.gameObject.SetActive(false);EditorUtility.SetDirty(m.course.weather);}
